CREATE TABLE IF NOT EXISTS posts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL DEFAULT '',body TEXT NOT NULL,career_id TEXT NOT NULL DEFAULT '',course_id TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,hidden INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS posts_feed ON posts(hidden,career_id,created_at);
CREATE TABLE IF NOT EXISTS post_comments(id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,parent_id TEXT REFERENCES post_comments(id) ON DELETE CASCADE,body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS comments_post ON post_comments(post_id,created_at);
CREATE TABLE IF NOT EXISTS post_marks(post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('useful','saved')),PRIMARY KEY(post_id,user_id,kind));
CREATE TABLE IF NOT EXISTS comment_votes(comment_id TEXT NOT NULL REFERENCES post_comments(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(comment_id,user_id));
CREATE TABLE IF NOT EXISTS community_reports(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,reason TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,post_id));
CREATE TABLE IF NOT EXISTS user_blocks(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,blocked_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(user_id,blocked_id));
CREATE TABLE IF NOT EXISTS community_files(id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,data BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS activity_notices(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,post_id TEXT REFERENCES posts(id) ON DELETE CASCADE,created_at TEXT NOT NULL,seen INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS activity_owner ON activity_notices(user_id,created_at);
CREATE TABLE IF NOT EXISTS grade_targets(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,course_id TEXT NOT NULL,target REAL NOT NULL CHECK(target BETWEEN 0 AND 20),PRIMARY KEY(user_id,course_id));
CREATE TABLE IF NOT EXISTS ai_consents(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,version TEXT NOT NULL,accepted_at TEXT NOT NULL,revoked_at TEXT);
CREATE TABLE IF NOT EXISTS document_results(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,file_id TEXT NOT NULL REFERENCES attachments(id) ON DELETE CASCADE,kind TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS document_owner ON document_results(user_id,file_id,created_at);
CREATE TABLE IF NOT EXISTS quiz_attempts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,result_id TEXT NOT NULL REFERENCES document_results(id) ON DELETE CASCADE,answers TEXT NOT NULL,score INTEGER NOT NULL,total INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS calendar_sync_settings(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,enabled INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'idle',error TEXT NOT NULL DEFAULT '',last_sync TEXT,attempts INTEGER NOT NULL DEFAULT 0,next_try TEXT);
CREATE TABLE IF NOT EXISTS app_private_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS push_subscriptions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,subscription TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS push_owner ON push_subscriptions(user_id);
CREATE TABLE IF NOT EXISTS notification_settings(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,tasks INTEGER NOT NULL DEFAULT 1,community INTEGER NOT NULL DEFAULT 1,quiet_start INTEGER NOT NULL DEFAULT 22,quiet_end INTEGER NOT NULL DEFAULT 7);
CREATE TABLE IF NOT EXISTS push_attempts(notice_id TEXT NOT NULL,subscription_id TEXT NOT NULL REFERENCES push_subscriptions(id) ON DELETE CASCADE,state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_try TEXT,PRIMARY KEY(notice_id,subscription_id));
CREATE TABLE IF NOT EXISTS task_positions(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,task_ids TEXT NOT NULL);
